-- FUNCTIONS

DELIMITER $$
DROP FUNCTION IF EXISTS fn_media_avaliacoes_historia$$
CREATE FUNCTION fn_media_avaliacoes_historia(pn_hist_id INT)
RETURNS DECIMAL(5,2)
NOT DETERMINISTIC
READS SQL DATA
BEGIN
/*
DATA: 29/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Calcular a média das notas recebidas por uma história específica.
*/
    -- Variável que armazenará a média calculada.
    DECLARE vn_media DECIMAL(5,2);

    -- Calcula a média das notas somente da história recebida como parâmetro.
    SELECT AVG(avai_nota) INTO vn_media
    FROM avaliacao WHERE hist_id = pn_hist_id;

    -- Devolve a média; se não houver avaliações, AVG retorna NULL.
    RETURN vn_media;
END$$
DELIMITER ;

DELIMITER $$
DROP FUNCTION IF EXISTS fn_total_comentarios_historia$$
CREATE FUNCTION fn_total_comentarios_historia(pn_hist_id INT)
RETURNS INT
NOT DETERMINISTIC
READS SQL DATA
BEGIN
/*
DATA: 29/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Contar quantos comentários estão cadastrados para uma história específica.
*/
    -- Variável que armazenará a quantidade de comentários.
    DECLARE vn_total INT;

    -- Conta apenas os comentários associados à história informada.
    SELECT COUNT(*) INTO vn_total FROM comentario WHERE hist_id = pn_hist_id;

    -- Devolve a quantidade encontrada.
    RETURN vn_total;
END$$
DELIMITER ;

DELIMITER $$
DROP FUNCTION IF EXISTS fn_total_historias_cadastradas$$
CREATE FUNCTION fn_total_historias_cadastradas()
RETURNS INT
NOT DETERMINISTIC
READS SQL DATA
BEGIN
/*
DATA: 29/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Retornar a quantidade total de histórias cadastradas no sistema.
*/
    -- Variável que armazenará o total de histórias.
    DECLARE vn_total INT;

    -- Conta todas as histórias cadastradas na tabela.
    SELECT COUNT(*) INTO vn_total FROM historia;

    -- Devolve o total calculado.
    RETURN vn_total;
END$$
DELIMITER ;

-- PROCEDURES

DELIMITER $$
DROP PROCEDURE IF EXISTS pc_cadastrar_pessoa$$
CREATE PROCEDURE pc_cadastrar_pessoa(IN ps_nome VARCHAR(100), IN ps_email VARCHAR(255), IN ps_senha VARCHAR(200))
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Validar os dados informados e cadastrar uma nova pessoa com perfil de Usuário e status Ativo, vinculando seu e-mail.
*/
    DECLARE vn_perf_id INT DEFAULT NULL;
    DECLARE vn_pess_id INT DEFAULT NULL;

    -- Impede cadastro sem nome.
    IF ps_nome IS NULL OR TRIM(ps_nome) = "" THEN
        SELECT "Informe o nome da pessoa." AS MENSAGEM;

    -- Valida se o e-mail foi informado e possui um formato básico válido.
    ELSEIF ps_email IS NULL
        OR TRIM(ps_email) = ""
        OR ps_email NOT LIKE "%_@_%._%" THEN
        SELECT "Informe um e-mail válido." AS MENSAGEM;

    -- Exige senha com pelo menos oito caracteres.
    ELSEIF ps_senha IS NULL OR CHAR_LENGTH(TRIM(ps_senha)) < 8 THEN
        SELECT "A senha informada é inválida." AS MENSAGEM;

    -- Não permite cadastrar um e-mail que já pertença a outra conta.
    ELSEIF EXISTS (SELECT 1 FROM email WHERE emai_nome = TRIM(ps_email)) THEN
        SELECT "Este e-mail já está cadastrado." AS MENSAGEM;

    ELSE
        -- Localiza o ID do perfil padrão de quem se cadastra pelo site.
        SELECT perf_id
        INTO vn_perf_id
        FROM perfil
        WHERE perf_nome = "Usuário"
        LIMIT 1;

        -- Se o perfil não estiver cadastrado, informa o problema.
        IF vn_perf_id IS NULL THEN
            SELECT "O perfil Usuário não foi encontrado." AS MENSAGEM;

        ELSE
            -- Cria a pessoa como ativa e associa o perfil Usuário.
            INSERT INTO pessoa (pess_nome, pess_senha, pess_status, perf_id)
            VALUES (TRIM(ps_nome), ps_senha, "Ativo", vn_perf_id);

            -- Guarda o ID da pessoa recém-criada.
            SET vn_pess_id = LAST_INSERT_ID();

            -- Registra o e-mail associado à pessoa.
            INSERT INTO email (emai_nome, pess_id)
            VALUES (TRIM(ps_email), vn_pess_id);

            SELECT
                "Pessoa cadastrada com sucesso." AS MENSAGEM,
                vn_pess_id AS PESS_ID;
        END IF;
    END IF;
END$$
DELIMITER ;

DELIMITER $$
DROP PROCEDURE IF EXISTS pc_alterar_pessoa$$
CREATE PROCEDURE pc_alterar_pessoa(IN pn_pess_id INT, IN ps_nome VARCHAR(100), IN ps_senha VARCHAR(200))
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Alterar o nome e a senha de uma pessoa existente, mantendo o e-mail cadastrado sem alterações.
*/
    -- Verifica se a pessoa que será alterada existe.
    IF NOT EXISTS (SELECT 1 FROM pessoa WHERE pess_id = pn_pess_id) THEN
        SELECT "Pessoa não encontrada." AS MENSAGEM;

    -- Impede salvar um nome vazio.
    ELSEIF ps_nome IS NULL OR TRIM(ps_nome) = "" THEN
        SELECT "Informe o nome da pessoa." AS MENSAGEM;

    -- Exige senha com pelo menos oito caracteres.
    ELSEIF ps_senha IS NULL OR CHAR_LENGTH(TRIM(ps_senha)) < 8 THEN
        SELECT "A senha informada é inválida." AS MENSAGEM;

    ELSE
        -- Atualiza apenas o nome e a senha.
        UPDATE pessoa
        SET pess_nome = TRIM(ps_nome),
            pess_senha = ps_senha
        WHERE pess_id = pn_pess_id;

        SELECT "Pessoa alterada com sucesso." AS MENSAGEM;
    END IF;
END$$
DELIMITER ;

DELIMITER $$
DROP PROCEDURE IF EXISTS pc_excluir_pessoa$$
CREATE PROCEDURE pc_excluir_pessoa(IN pn_admin_id INT, IN pn_pess_id INT)
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Permitir que um administrador ativo exclua uma conta de usuário, respeitando as restrições de segurança e removendo seus dados relacionados.
*/

    DECLARE vn_perf_admin INT DEFAULT NULL;
    DECLARE vn_perf_alvo INT DEFAULT NULL;
    DECLARE vn_status_admin VARCHAR(10) DEFAULT NULL;

    -- Busca o perfil e o status de quem solicita a exclusão.
    SELECT perf_id, pess_status
    INTO vn_perf_admin, vn_status_admin
    FROM pessoa
    WHERE pess_id = pn_admin_id
    LIMIT 1;

    -- Busca o perfil da conta que será excluída.
    SELECT perf_id
    INTO vn_perf_alvo
    FROM pessoa
    WHERE pess_id = pn_pess_id
    LIMIT 1;

    -- Permite a exclusão somente por administrador ativo.
    IF vn_perf_admin IS NULL
        OR vn_perf_admin <> 1
        OR vn_status_admin <> "Ativo" THEN
        SELECT "Ação permitida somente para administrador ativo." AS MENSAGEM;

    -- Impede que o administrador exclua a própria conta.
    ELSEIF pn_admin_id = pn_pess_id THEN
        SELECT "Não é permitido excluir a própria conta." AS MENSAGEM;

    -- Confirma que a conta-alvo existe.
    ELSEIF vn_perf_alvo IS NULL THEN
        SELECT "Pessoa não encontrada." AS MENSAGEM;

    -- Protege as contas de administrador contra exclusão.
    ELSEIF vn_perf_alvo = 1 THEN
        SELECT "Não é permitido excluir uma conta de administrador." AS MENSAGEM;

    -- Impede excluir uma pessoa responsável por histórias cadastradas.
    ELSEIF EXISTS (SELECT 1 FROM historia  WHERE pess_id = pn_pess_id) THEN
        SELECT "Não é possível excluir esta pessoa porque ela possui histórias cadastradas." AS MENSAGEM;

    ELSE
        -- Evita enviar notificações à conta que será excluída.
        SET @user_pess_id = NULL;

        -- Remove os comentários da pessoa.
        DELETE FROM comentario
        WHERE pess_id = pn_pess_id;

        SET @user_pess_id = NULL;

        -- Remove as avaliações feitas pela pessoa.
        DELETE FROM avaliacao
        WHERE pess_id = pn_pess_id;

        -- Remove os vínculos das notificações recebidas.
        DELETE FROM pessoa_notificacao
        WHERE pess_id = pn_pess_id;

        -- Exclui o e-mail associado à pessoa.
        DELETE FROM email
        WHERE pess_id = pn_pess_id;

        -- Exclui o registro principal da pessoa.
        DELETE FROM pessoa
        WHERE pess_id = pn_pess_id;

        SELECT "Pessoa excluída com sucesso." AS MENSAGEM;
    END IF;
END$$
DELIMITER ;

DELIMITER $$
DROP PROCEDURE IF EXISTS pc_alterar_perfil_pessoa$$
CREATE PROCEDURE pc_alterar_perfil_pessoa(IN pn_admin_id INT, IN pn_pess_id INT, IN pn_perf_id INT)
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Permitir que um administrador ativo altere o perfil de outra pessoa, sem deixar o sistema sem administrador ativo.
*/

    DECLARE vn_perf_admin INT DEFAULT NULL;
    DECLARE vn_status_admin VARCHAR(10) DEFAULT NULL;
    DECLARE vn_perf_atual INT DEFAULT NULL;

    -- Consulta o perfil e o status de quem solicita a alteração.
    SELECT perf_id, pess_status
    INTO vn_perf_admin, vn_status_admin
    FROM pessoa
    WHERE pess_id = pn_admin_id
    LIMIT 1;

    -- Consulta o perfil atual da pessoa-alvo.
    SELECT perf_id
    INTO vn_perf_atual
    FROM pessoa
    WHERE pess_id = pn_pess_id
    LIMIT 1;

    -- Permite a alteração somente por administrador ativo.
    IF vn_perf_admin IS NULL
        OR vn_perf_admin <> 1
        OR vn_status_admin <> "Ativo" THEN
        SELECT "Ação permitida somente para administrador ativo." AS MENSAGEM;

    -- Impede alterar o próprio perfil.
    ELSEIF pn_admin_id = pn_pess_id THEN
        SELECT "Não é permitido alterar o próprio perfil." AS MENSAGEM;

    -- Verifica se a pessoa-alvo existe.
    ELSEIF vn_perf_atual IS NULL THEN
        SELECT "Pessoa não encontrada." AS MENSAGEM;

    -- Aceita somente os perfis 1 (Administrador) e 2 (Usuário).
    ELSEIF pn_perf_id NOT IN (1, 2) THEN
        SELECT "Perfil inválido." AS MENSAGEM;

    -- Impede rebaixar o último administrador ativo.
    ELSEIF vn_perf_atual = 1
        AND pn_perf_id = 2
        AND (SELECT COUNT(*) FROM pessoa WHERE perf_id = 1
              AND pess_status = "Ativo"
              AND pess_id <> pn_pess_id) = 0 THEN
        SELECT "Não é possível rebaixar o último administrador ativo." AS MENSAGEM;

    ELSE
        -- Altera o perfil da pessoa selecionada.
        UPDATE pessoa
        SET perf_id = pn_perf_id
        WHERE pess_id = pn_pess_id;

        SELECT "Perfil alterado com sucesso." AS MENSAGEM;
    END IF;
END$$
DELIMITER ;

DELIMITER $$
DROP PROCEDURE IF EXISTS pc_alterar_status_pessoa$$
CREATE PROCEDURE pc_alterar_status_pessoa(IN pn_admin_id INT, IN pn_pess_id INT, IN ps_status VARCHAR(10))
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Permitir que um administrador ativo ative ou inative outra pessoa, protegendo a existência de pelo menos um administrador ativo.
*/

    DECLARE vn_perf_admin INT DEFAULT NULL;
    DECLARE vn_status_admin VARCHAR(10) DEFAULT NULL;
    DECLARE vn_perf_alvo INT DEFAULT NULL;
    DECLARE vn_status_alvo VARCHAR(10) DEFAULT NULL;

    -- Consulta o perfil e o status de quem solicita a alteração.
    SELECT perf_id, pess_status
    INTO vn_perf_admin, vn_status_admin
    FROM pessoa
    WHERE pess_id = pn_admin_id
    LIMIT 1;

    -- Consulta o perfil e o status atuais da pessoa-alvo.
    SELECT perf_id, pess_status
    INTO vn_perf_alvo, vn_status_alvo
    FROM pessoa
    WHERE pess_id = pn_pess_id
    LIMIT 1;

    -- Permite a alteração somente por administrador ativo.
    IF vn_perf_admin IS NULL
        OR vn_perf_admin <> 1
        OR vn_status_admin <> "Ativo" THEN
        SELECT "Ação permitida somente para administrador ativo." AS MENSAGEM;

    -- Impede alterar o próprio status.
    ELSEIF pn_admin_id = pn_pess_id THEN
        SELECT "Não é permitido alterar o próprio status." AS MENSAGEM;

    -- Confirma que a pessoa-alvo existe.
    ELSEIF vn_perf_alvo IS NULL THEN
        SELECT "Pessoa não encontrada." AS MENSAGEM;

    -- Aceita somente os status Ativo ou Inativo.
    ELSEIF ps_status NOT IN ("Ativo", "Inativo") THEN
        SELECT "Status inválido." AS MENSAGEM;

    -- Impede inativar o último administrador ativo.
    ELSEIF vn_perf_alvo = 1
        AND vn_status_alvo = "Ativo"
        AND ps_status = "Inativo"
        AND (SELECT COUNT(*) FROM pessoa WHERE perf_id = 1
              AND pess_status = "Ativo"
              AND pess_id <> pn_pess_id) = 0 THEN
        SELECT "Não é possível inativar el último administrador ativo." AS MENSAGEM;

    ELSE
        -- Atualiza o status da pessoa selecionada.
        UPDATE pessoa
        SET pess_status = ps_status
        WHERE pess_id = pn_pess_id;

        SELECT "Status alterado com sucesso." AS MENSAGEM;
    END IF;
END$$
DELIMITER ;

-- TRIGGERS

DELIMITER $$
DROP TRIGGER IF EXISTS tg_avaliacao_notificacao_pos_ins $$
CREATE TRIGGER tg_avaliacao_notificacao_pos_ins 
AFTER INSERT ON avaliacao 
FOR EACH ROW 
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Criar ou atualizar uma notificação agrupada para avisar os administradores ativos sobre as avaliações recebidas por uma história.
*/
    -- Variáveis usadas para guardar o ID da notificação, a quantidade de avaliações,o perfil de quem avaliou e o título da história.
    DECLARE vn_noti_id INT DEFAULT NULL;
    DECLARE vn_total INT DEFAULT 0;
    DECLARE vs_perfil VARCHAR(100);
    DECLARE vs_titulo VARCHAR(255);

    -- Identifica o perfil de quem acabou de avaliar a história.
    SELECT MAX(pf.perf_nome)
    INTO vs_perfil
    FROM pessoa ps
    INNER JOIN perfil pf ON pf.perf_id = ps.perf_id
    WHERE ps.pess_id = NEW.pess_id;

    -- Somente avaliações feitas por usuários geram notificação para os administradores.
    IF vs_perfil = "Usuário" THEN

        -- Conta todas as avaliações existentes para a história avaliada.
        SELECT COUNT(*)
        INTO vn_total
        FROM avaliacao
        WHERE hist_id = NEW.hist_id;

        -- Obtém o título da história para montar a mensagem da notificação.
        SELECT hiid_titulo
        INTO vs_titulo
        FROM historia_idioma
        WHERE hist_id = NEW.hist_id
        ORDER BY idio_id
        LIMIT 1;

        -- Verifica se já existe uma notificação de avaliações para esta história.
        SELECT MAX(n.noti_id)
        INTO vn_noti_id
        FROM notificacao n
        INNER JOIN historia_notificacao hn ON hn.noti_id = n.noti_id
        WHERE hn.hist_id = NEW.hist_id
        AND n.noti_titulo = "Novas avaliações";

        -- Se ainda não existe, cria a notificação pela primeira vez.
        IF vn_noti_id IS NULL THEN

            -- Cria a notificação com o título da história e o total atual de avaliações.
            INSERT INTO notificacao (noti_titulo, noti_mensagem, noti_data_hora)
            VALUES ("Novas avaliações", CONCAT("A história ", vs_titulo, " recebeu novas avaliações. Total de avaliações: ", vn_total, "."), NOW());
            -- Guarda o identificador gerado para relacionar a notificação à história e às pessoas.
            SET vn_noti_id = LAST_INSERT_ID();

            -- Registra a história à qual esta notificação pertence.
            INSERT INTO historia_notificacao (hist_id, noti_id, hino_data_hora)
            VALUES (NEW.hist_id, vn_noti_id, NOW());

            -- Entrega a notificação a todos os administradores ativos, como não lida.
            -- Envia a notificação não lida a todos os administradores ativos.
            INSERT INTO pessoa_notificacao (pess_id, noti_id, peno_lida)
            SELECT ps.pess_id, vn_noti_id, 0
            FROM pessoa ps
            INNER JOIN perfil pf ON pf.perf_id = ps.perf_id
            WHERE pf.perf_nome = "Administrador"
            AND ps.pess_status = "Ativo";
        ELSE
            -- Se já existe, atualiza a mensagem e a data em vez de criar outra notificação.
            UPDATE notificacao
            SET noti_mensagem = CONCAT("A história ", vs_titulo, " recebeu novas avaliações. Total de avaliações: ", vn_total, "."),
                noti_data_hora = NOW()
            WHERE noti_id = vn_noti_id;

            -- volta a marcar como não lida (e recria para quem tinha excluído)
            INSERT INTO pessoa_notificacao (pess_id, noti_id, peno_lida)
            SELECT ps.pess_id, vn_noti_id, 0
            FROM pessoa ps
            INNER JOIN perfil pf ON pf.perf_id = ps.perf_id
            WHERE pf.perf_nome = "Administrador"
            AND ps.pess_status = "Ativo"
            ON DUPLICATE KEY UPDATE peno_lida = 0, peno_data_hora = NOW();
        END IF;
    END IF;

END $$
DELIMITER ;

DELIMITER $$
DROP TRIGGER IF EXISTS tg_comentario_notificacao_pos_ins $$
CREATE TRIGGER tg_comentario_notificacao_pos_ins
AFTER INSERT ON comentario
FOR EACH ROW
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Notificar os administradores ativos quando um usuário publica um comentário, registrando o texto e a história relacionados.
*/
    DECLARE vs_perfil VARCHAR(100);
    DECLARE vs_nome VARCHAR(100);
    DECLARE vs_titulo VARCHAR(100);
    DECLARE vn_noti_id INT;

    -- Descobre o perfil e o nome da pessoa que escreveu o comentário.
    SELECT MAX(pf.perf_nome), MAX(ps.pess_nome)
    INTO vs_perfil, vs_nome
    FROM pessoa ps
    INNER JOIN perfil pf ON pf.perf_id = ps.perf_id
    WHERE ps.pess_id = NEW.pess_id;

    -- A notificação de novo comentário é destinada aos administradores quando o autor é usuário.
    IF vs_perfil = "Usuário" THEN
        -- Busca o título da história, priorizando o título em português.
        SELECT hiid_titulo INTO vs_titulo
        FROM historia_idioma
        WHERE hist_id = NEW.hist_id
        ORDER BY (idio_id = 1) DESC, idio_id
        LIMIT 1;

        -- Cria a notificação com o nome do autor, o título da história e o texto do comentário.
        INSERT INTO notificacao (noti_titulo, noti_mensagem, noti_data_hora)
        VALUES ("Novo comentário", CONCAT("O usuário ", vs_nome, " comentou na história ", vs_titulo, ". Comentário: ", NEW.come_texto), NOW());
        SET vn_noti_id = LAST_INSERT_ID();

        -- Relaciona a notificação com a história comentada.
        INSERT INTO historia_notificacao (hist_id, noti_id, hino_data_hora)
        VALUES (NEW.hist_id, vn_noti_id, NOW());

        -- Guarda o vínculo exato entre o comentário e sua notificação para permitir removê-la depois.
        INSERT INTO comentario_notificacao (come_id, noti_id)
        VALUES (NEW.come_id, vn_noti_id);

        -- Envia a notificação para todos os administradores ativos.
        -- Envia a notificação como não lida para todos os administradores ativos.
        INSERT INTO pessoa_notificacao (pess_id, noti_id, peno_lida)
        SELECT ps.pess_id, vn_noti_id, 0
        FROM pessoa ps
        INNER JOIN perfil pf ON pf.perf_id = ps.perf_id
        WHERE pf.perf_nome = "Administrador" AND ps.pess_status = "Ativo";
    END IF;
END $$
DELIMITER ;

DELIMITER $$
DROP TRIGGER IF EXISTS tg_comentario_notificacao_pos_del$$
CREATE TRIGGER tg_comentario_notificacao_pos_del
AFTER DELETE ON comentario
FOR EACH ROW
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Remover a notificação vinculada ao comentário excluído e avisar o autor quando a exclusão for realizada por um administrador.
*/
    DECLARE vn_noti_id INT DEFAULT NULL;
    DECLARE vs_perfil VARCHAR(100) DEFAULT NULL;
    DECLARE vs_titulo VARCHAR(100) DEFAULT NULL;

    -- Identifica o perfil da pessoa que está realizando a exclusão, usando o ID informado pela aplicação.
    SELECT MAX(pf.perf_nome) INTO vs_perfil
    FROM pessoa ps
    INNER JOIN perfil pf ON pf.perf_id = ps.perf_id
    WHERE ps.pess_id = @user_pess_id;

    -- Recupera a notificação específica criada para esse comentário.
    SELECT MAX(cn.noti_id) INTO vn_noti_id
    FROM comentario_notificacao cn
    WHERE cn.come_id = OLD.come_id;

    -- Compatibilidade com notificações antigas, criadas antes da tabela de vínculo.
    IF vn_noti_id IS NULL THEN
        -- Se não houver vínculo novo, tenta localizar uma notificação antiga pelo texto do comentário.
        SELECT MAX(n.noti_id) INTO vn_noti_id
        FROM notificacao n
        INNER JOIN historia_notificacao hn ON hn.noti_id = n.noti_id
        WHERE hn.hist_id = OLD.hist_id
          AND n.noti_titulo = "Novo comentário"
          AND RIGHT(n.noti_mensagem, CHAR_LENGTH(CONCAT("Comentário: ", OLD.come_texto))) = CONCAT("Comentário: ", OLD.come_texto);
    END IF;

    -- A notificação do comentário removido não deve continuar na lista dos administradores.
    IF vn_noti_id IS NOT NULL THEN
        -- Exclui primeiro os vínculos e depois a notificação, para ela desaparecer da lista dos administradores.
        DELETE FROM pessoa_notificacao WHERE noti_id = vn_noti_id;
        DELETE FROM historia_notificacao WHERE noti_id = vn_noti_id;
        DELETE FROM comentario_notificacao WHERE come_id = OLD.come_id;
        DELETE FROM notificacao WHERE noti_id = vn_noti_id;
    END IF;

    -- Só avisa o autor quando quem excluiu foi um administrador.
    IF vs_perfil = "Administrador" THEN
        -- Busca o título da história para informar ao autor em qual história o comentário foi removido.
        SELECT hiid_titulo INTO vs_titulo
        FROM historia_idioma
        WHERE hist_id = OLD.hist_id
        ORDER BY (idio_id = 1) DESC, idio_id
        LIMIT 1;

        -- Cria uma notificação informando ao autor que o administrador excluiu seu comentário.
        INSERT INTO notificacao (noti_titulo, noti_mensagem, noti_data_hora)
        VALUES ("Comentário excluído", CONCAT("Seu comentário na história ", vs_titulo, " foi excluído pelo administrador."), NOW());
        SET vn_noti_id = LAST_INSERT_ID();

        -- Associa o aviso à história em que o comentário estava publicado.
        INSERT INTO historia_notificacao (hist_id, noti_id, hino_data_hora)
        VALUES (OLD.hist_id, vn_noti_id, NOW());

        -- Envia a notificação diretamente à pessoa que escreveu o comentário.
        INSERT INTO pessoa_notificacao (pess_id, noti_id, peno_lida)
        VALUES (OLD.pess_id, vn_noti_id, 0);
    END IF;
END $$
DELIMITER ;

DELIMITER $$
DROP TRIGGER IF EXISTS tg_historia_idioma_notificacao_pos_ins $$
CREATE TRIGGER tg_historia_idioma_notificacao_pos_ins
AFTER INSERT ON historia_idioma
FOR EACH ROW
BEGIN
/*
DATA: 20/10/2026
AUTORA: Darliane Arza de Oliveira
OBJETIVO: Avisar as pessoas ativas quando uma história é cadastrada em português, evitando criar notificações duplicadas para a mesma história.
*/
    DECLARE vn_noti_id INT DEFAULT NULL;
    DECLARE vs_titulo VARCHAR(100) DEFAULT NULL;

    -- Só gera a notificação quando o idioma inserido é Português (idio_id = 1).
    IF NEW.idio_id = 1 THEN
        -- Busca o título em português usado no texto da notificação.
        SELECT hiid_titulo INTO vs_titulo
        FROM historia_idioma
        WHERE hist_id = NEW.hist_id AND idio_id = 1
        LIMIT 1;

        -- Procura uma notificação de publicação já associada a esta história.
        SELECT MAX(n.noti_id) INTO vn_noti_id
        FROM notificacao n
        INNER JOIN historia_notificacao hn ON hn.noti_id = n.noti_id
        WHERE hn.hist_id = NEW.hist_id
          AND n.noti_titulo = "Nova história adicionada!";

        IF vn_noti_id IS NULL THEN
            -- Cria uma única notificação de publicação para a história.
            INSERT INTO notificacao (noti_titulo, noti_mensagem, noti_data_hora)
            VALUES (
                "Nova história adicionada!",
                CONCAT("Uma nova história foi publicada: ", vs_titulo, "."),
                NOW()
            );
            -- Recupera o ID da notificação recém-criada.
            SET vn_noti_id = LAST_INSERT_ID();

            -- Relaciona a notificação com a história publicada.
            INSERT INTO historia_notificacao (hist_id, noti_id, hino_data_hora)
            VALUES (NEW.hist_id, vn_noti_id, NOW());

            -- Entrega a notificação a todas as pessoas ativas, inicialmente como não lida.
            INSERT INTO pessoa_notificacao (pess_id, noti_id, peno_lida)
            SELECT ps.pess_id, vn_noti_id, 0
            FROM pessoa ps
            WHERE ps.pess_status = "Ativo";
        END IF;
    END IF;
END$$
DELIMITER ;

-- VIEWS

-- Lista pessoas com e-mail, perfil e status.
CREATE OR REPLACE VIEW vw_usuarios AS
SELECT p.pess_id, p.pess_nome, e.emai_nome, pf.perf_id, pf.perf_nome, p.pess_status
FROM pessoa p
INNER JOIN perfil pf ON pf.perf_id = p.perf_id
LEFT JOIN email e ON e.pess_id = p.pess_id;

-- Reúne as histórias com título, texto, idioma, categoria e pessoa responsável.
CREATE OR REPLACE VIEW vw_historias AS
SELECT h.hist_id, hi.hiid_titulo, hi.hiid_legenda_imagem, hi.hiid_texto,
       i.idio_id, i.idio_nome, c.cate_nome, h.pess_id
FROM historia h
INNER JOIN historia_idioma hi ON hi.hist_id = h.hist_id
INNER JOIN idioma i ON i.idio_id = hi.idio_id
INNER JOIN categoria c ON c.cate_id = h.cate_id;

-- Lista comentários junto do autor e do título em português da história.
CREATE OR REPLACE VIEW vw_comentarios AS
SELECT c.come_id, c.come_texto, c.come_data_pessoa, p.pess_id, p.pess_nome,
       h.hist_id, hi.hiid_titulo
FROM comentario c
INNER JOIN pessoa p ON p.pess_id = c.pess_id
INNER JOIN historia h ON h.hist_id = c.hist_id
LEFT JOIN historia_idioma hi ON hi.hist_id = h.hist_id AND hi.idio_id = 1;

-- Lista avaliações junto do autor e do título em português da história.
CREATE OR REPLACE VIEW vw_avaliacoes AS
SELECT a.avai_id, a.avai_nota, a.avai_data_hora, p.pess_id, p.pess_nome,
       h.hist_id, hi.hiid_titulo
FROM avaliacao a
INNER JOIN pessoa p ON p.pess_id = a.pess_id
INNER JOIN historia h ON h.hist_id = a.hist_id
LEFT JOIN historia_idioma hi ON hi.hist_id = h.hist_id AND hi.idio_id = 1;

-- Mostra as notificações vinculadas a cada pessoa e se já foram lidas.
CREATE OR REPLACE VIEW vw_notificacoes AS
SELECT pn.pess_id, n.noti_id, n.noti_titulo, n.noti_mensagem, n.noti_data_hora,
       pn.peno_data_hora, pn.peno_lida
FROM pessoa_notificacao pn
INNER JOIN notificacao n ON n.noti_id = pn.noti_id;
SET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;
SET UNIQUE_CHECKS=@OLD_UNIQUE_CHECKS;
SET SQL_MODE=@OLD_SQL_MODE;
